local addonName, ns = ...

-- Tiles are generated by tools/mapgen/export.py. Tiles.lua sets
-- ns.tiles[uiMapID] = { rows, cols, labels = { { areaID, x, y } }, caves = { { areaID, x, y, name } } }.
ns.tiles = ns.tiles or {}

local TILE_PATH = "Interface\\AddOns\\ClearMap\\Tiles\\%d\\%d_%d"
local FADE_PATH = "Interface\\AddOns\\ClearMap\\Tiles\\%d\\fade"
local CIRCLE_MASK = "Interface\\CharacterFrame\\TempPortraitAlphaMask"
local LABEL_COLOR = { 0.29, 0.18, 0.11 }
local LABEL_HALO = { 1, 0.96, 0.88, 0.9 }
local defaults = { enabled = true, labels = false, minimap = true }

-- Our textures per Blizzard detail layer frame. Kept in our own table so no Blizzard table is written to.
local layerTextures = {}
local button, overlay
local cavePins, labelFrames = {}, {}

local function GridFor(mapID)
    return ns.db.enabled and mapID and ns.tiles[mapID]
end

-- Cover a detail layer with our tiles, or give it back to Blizzard's tiles.
local function ApplyLayer(layer, mapID)
    local grid = GridFor(mapID)
    -- Alpha, not Hide: Blizzard keeps the whole layer invisible until its own tiles report loaded.
    for tile in layer.detailTilePool:EnumerateActive() do
        tile:SetAlpha(grid and 0 or 1)
    end
    local list = layerTextures[layer] or {}
    layerTextures[layer] = list
    local used = 0
    if grid then
        local art = C_Map.GetMapArtLayers(mapID)[1]
        local w, h = art.layerWidth / grid.cols, art.layerHeight / grid.rows
        for row = 0, grid.rows - 1 do
            for col = 0, grid.cols - 1 do
                used = used + 1
                local tex = list[used] or layer:CreateTexture()
                list[used] = tex
                tex:SetDrawLayer("BACKGROUND", -7)
                tex:ClearAllPoints()
                tex:SetPoint("TOPLEFT", layer, "TOPLEFT", col * w, -row * h)
                tex:SetSize(w, h)
                tex:SetTexture(TILE_PATH:format(mapID, row, col), nil, nil, "TRILINEAR")
                tex:Show()
            end
        end
        -- Tiles are shared with the minimap, so the world map lays the neighbor-zone fade on top here.
        used = used + 1
        local fade = list[used] or layer:CreateTexture()
        list[used] = fade
        fade:SetDrawLayer("BACKGROUND", -6)
        fade:ClearAllPoints()
        fade:SetPoint("TOPLEFT", layer, "TOPLEFT", 0, 0)
        fade:SetSize(art.layerWidth, art.layerHeight)
        fade:SetTexture(FADE_PATH:format(mapID), nil, nil, "TRILINEAR")
        fade:Show()
    end
    for i = used + 1, #list do
        list[i]:Hide()
    end
end

-- The explored-area overlays are Blizzard art drawn on top of the base tiles. Hide them on our maps.
local function ApplyExploration(pin, mapID)
    pin:SetShown(not GridFor(mapID))
end

local function CircleTexture(parent, layer, size, r, g, b)
    local tex = parent:CreateTexture(nil, layer)
    tex:SetPoint("CENTER")
    tex:SetSize(size, size)
    tex:SetColorTexture(r, g, b)
    tex:SetMask(CIRCLE_MASK)
    return tex
end

local function CreateCavePin()
    local pin = CreateFrame("Frame", nil, overlay)
    pin:SetSize(11, 11)
    pin:SetMouseMotionEnabled(true)
    pin:SetMouseClickEnabled(false) -- clicks fall through to the map
    CircleTexture(pin, "ARTWORK", 11, 0.98, 0.95, 0.89)
    CircleTexture(pin, "OVERLAY", 8, 0.31, 0.18, 0.13)
    pin:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
        GameTooltip:SetText(self.name)
        GameTooltip:AddLine("Cave entrance", 1, 1, 1)
        GameTooltip:Show()
    end)
    pin:SetScript("OnLeave", function()
        GameTooltip:Hide()
    end)
    return pin
end

local function CreateLabel()
    local frame = CreateFrame("Frame", nil, overlay)
    frame:SetSize(1, 1)
    frame.text = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    frame.text:SetPoint("CENTER")
    frame.text:SetTextColor(unpack(LABEL_COLOR))
    frame.text:SetShadowColor(unpack(LABEL_HALO))
    frame.text:SetShadowOffset(1, -1)
    return frame
end

-- Keep pins and labels the same size on screen at every zoom level.
local function PlaceOverlay()
    if not overlay or not overlay:IsShown() then return end
    local s = 1 / WorldMapFrame:GetCanvasScale()
    for _, list in ipairs({ cavePins, labelFrames }) do
        for _, f in ipairs(list) do
            if f:IsShown() then
                f:SetScale(s)
                f:ClearAllPoints()
                -- Offsets are in the child's own scale, so divide by it.
                f:SetPoint("CENTER", overlay, "TOPLEFT", f.x * overlay.w / s, -f.y * overlay.h / s)
            end
        end
    end
end

local function Fill(list, entries, create, setup)
    for i, entry in ipairs(entries) do
        local f = list[i] or create()
        list[i] = f
        f.x, f.y = entry[2], entry[3]
        f:SetShown(setup(f, entry))
    end
    for i = #entries + 1, #list do
        list[i]:Hide()
    end
end

local function UpdateOverlay(mapID)
    local data = GridFor(mapID)
    overlay:SetShown(data and true or false)
    if not data then return end
    local art = C_Map.GetMapArtLayers(mapID)[1]
    overlay.w, overlay.h = art.layerWidth, art.layerHeight
    Fill(cavePins, data.caves or {}, CreateCavePin, function(pin, cave)
        local info = cave[1] > 0 and C_Map.GetAreaInfo(cave[1])
        pin.name = info or (cave[4] ~= "" and cave[4]) or "Cave"
        return true
    end)
    Fill(labelFrames, ns.db.labels and data.labels or {}, CreateLabel, function(frame, label)
        local name = C_Map.GetAreaInfo(label[1])
        frame.text:SetText(name or "")
        return name ~= nil
    end)
    PlaceOverlay()
end

local function Refresh()
    local map = WorldMapFrame
    local mapID = map:GetMapID()
    for layer in map.detailLayerPool:EnumerateActive() do
        ApplyLayer(layer, mapID)
    end
    for pin in map:EnumeratePinsByTemplate("MapExplorationPinTemplate") do
        ApplyExploration(pin, mapID)
    end
    UpdateOverlay(mapID)
    button:SetText(ns.db.enabled and "ClearMap: On" or "ClearMap: Off")
    button:SetShown(ns.tiles[mapID] ~= nil)
end

local function Toggle()
    ns.enabledSetting:SetValue(not ns.db.enabled) -- goes through the setting so the options panel stays in sync
end

local function RegisterSettings()
    local category = Settings.RegisterVerticalLayoutCategory("ClearMap")
    local function Checkbox(key, name, tooltip)
        local setting = Settings.RegisterAddOnSetting(category, "ClearMap_" .. key, key, ns.db, "boolean", name, defaults[key])
        setting:SetValueChangedCallback(function()
            if button then Refresh() end
        end)
        Settings.CreateCheckbox(category, setting, tooltip)
        return setting
    end
    ns.enabledSetting = Checkbox("enabled", "Enabled",
        "Show ClearMap tiles and cave entrances on maps that have them. The button on the world map does the same.")
    Checkbox("minimap", "Minimap",
        "Use ClearMap tiles on the minimap too. It falls back to Blizzard's minimap indoors, in instances and while the minimap rotates.")
    Checkbox("labels", "Area names",
        "Write the names of areas onto the map. Off by default, because Blizzard's map already shows them on mouseover.")
    Settings.RegisterAddOnCategory(category)
end

local function Setup()
    local map = WorldMapFrame
    hooksecurefunc(map, "RefreshDetailLayers", Refresh)
    hooksecurefunc(map, "OnCanvasScaleChanged", PlaceOverlay)
    for pin in map:EnumeratePinsByTemplate("MapExplorationPinTemplate") do
        hooksecurefunc(pin, "RefreshOverlays", function(p)
            ApplyExploration(p, map:GetMapID())
        end)
    end

    -- Above the map tiles, below Blizzard's own pins, and never catching clicks.
    overlay = CreateFrame("Frame", nil, map:GetCanvas())
    overlay:SetAllPoints()
    overlay:Hide()

    button = CreateFrame("Button", nil, map.ScrollContainer, "UIPanelButtonTemplate")
    button:SetSize(110, 22)
    button:SetPoint("BOTTOMLEFT", map.ScrollContainer, "BOTTOMLEFT", 8, 8)
    button:SetFrameLevel(map.ScrollContainer:GetFrameLevel() + 50)
    button:SetScript("OnClick", Toggle)
    Refresh()
end

local frame = CreateFrame("Frame")
frame:SetScript("OnEvent", function(self, event, ...)
    self[event](self, ...)
end)
frame:RegisterEvent("ADDON_LOADED")
frame:RegisterEvent("PLAYER_LOGIN")

function frame:ADDON_LOADED(name)
    if name == addonName then
        ClearMapDB = ClearMapDB or {}
        for key, value in pairs(defaults) do
            if ClearMapDB[key] == nil then
                ClearMapDB[key] = value
            end
        end
        ns.db = ClearMapDB
        RegisterSettings()
    elseif name == "Blizzard_WorldMap" and ns.db and not button then
        Setup()
    end
end

function frame:PLAYER_LOGIN()
    if WorldMapFrame and not button then
        Setup()
    end
    ns.SetupMinimap()
end

SLASH_CLEARMAP1 = "/clearmap"
SlashCmdList.CLEARMAP = function()
    Toggle()
    print(addonName .. ": " .. (ns.db.enabled and "on" or "off"))
end
